def max_sum(triangle, n):
    if n == 0:
        return 0
    if n == 1:
        return triangle[0][0]
    for i in range(1, len(triangle)):
        triangle[i][0] += triangle[i-1][0]
        triangle[i][-1] += triangle[i-1][-1]
    for i in range(2, len(triangle)):
